    if (pageStatus === "Add" || pageStatus === "Clone") {
      this.setData({ sqt_plant: currentDept });
    }
  } else {
    this.disabled("sqt_plant", true);

    if (pageStatus === "Add" || pageStatus === "Clone") {
      this.setData({ sqt_plant: currentDept });
    }
