};

const fetchUnrestrictedQty = async () => {
  try {
    console.log("fetchUnrestrictedQty");
    const tableSQT = this.getValue("table_sqt");
    const plantId = this.getValue("sqt_plant");
    const organizationId = this.getValue("organization_id");

    console.log("tableSQT", tableSQT);

    if (tableSQT.length > 0) {
      // 创建更新数据的对象，避免在循环中多次调用setData
      const updateData = {};

      for (const [index, sqt] of tableSQT.entries()) {
        const itemId = sqt.material_id;

        let totalUnrestrictedQtyBase = 0;

        let item_batch_management = 0;
        let serial_number_management = 0;
        let stock_control = 0;

        await db
          .collection("Item")
          .where({ id: itemId })
          .get()
          .then((res) => {
            const itemData = res.data[0];
            item_batch_management = itemData.item_batch_management;
            serial_number_management = itemData.serial_number_management;
            stock_control = itemData.stock_control;
          });

        if (serial_number_management === 1) {
          const resSerialBalance = await db
            .collection("item_serial_balance")
            .where({
              material_id: itemId,
              ...(plantId !== organizationId
                ? { plant_id: plantId || null }
                : {}),
              organization_id: organizationId,
            })
            .get();
          console.log("wzplog", resSerialBalance);
          if (resSerialBalance && resSerialBalance.data.length > 0) {
            const serialBalanceData = resSerialBalance.data;

            totalUnrestrictedQtyBase = serialBalanceData.reduce(
              (sum, balance) => sum + (balance.unrestricted_qty || 0),
              0
            );
          }
        } else if (
          (serial_number_management !== 1 || !serial_number_management) &&
          item_batch_management === 1 &&
          (stock_control !== 0 || stock_control)
        ) {
          const resBatchBalance = await db
            .collection("item_batch_balance")
            .where({
              material_id: itemId,
              ...(plantId !== organizationId
                ? { plant_id: plantId || null }
                : {}),
              organization_id: organizationId,
            })
            .get();

          if (resBatchBalance && resBatchBalance.data.length > 0) {
            const batchBalanceData = resBatchBalance.data;

            totalUnrestrictedQtyBase = batchBalanceData.reduce(
              (sum, balance) => sum + (balance.unrestricted_qty || 0),
              0
            );
          }
        } else if (
          (serial_number_management !== 1 || !serial_number_management) &&
          (item_batch_management !== 1 || !item_batch_management) &&
          (stock_control !== 0 || stock_control)
        ) {
          const resBalance = await db
            .collection("item_balance")
            .where({
              material_id: itemId,
              ...(plantId !== organizationId
                ? { plant_id: plantId || null }
                : {}),
              organization_id: organizationId,
            })
            .get();

          if (resBalance && resBalance.data.length > 0) {
            const balanceData = resBalance.data;

            totalUnrestrictedQtyBase = balanceData.reduce(
              (sum, balance) => sum + (balance.unrestricted_qty || 0),
              0
            );
          }
        } else {
          console.log("No stock control for item", itemId);
          totalUnrestrictedQtyBase = 0;
        }

        console.log("totalUnrestrictedQtyBase", totalUnrestrictedQtyBase);
        console.log("index", index);

        // 将更新数据添加到对象中，而不是立即调用setData
        updateData[`table_sqt.${index}.unrestricted_qty`] =
          parseFloat(totalUnrestrictedQtyBase.toFixed(3)) || 0;
      }

      // 循环结束后一次性更新所有数据
      this.setData(updateData);
    }
  } catch (error) {
    console.error(error);
  }
};

(async () => {
  try {
    const status = await this.getValue("sqt_status");

    let pageStatus = "";

    if (this.isAdd) pageStatus = "Add";
    else if (this.isEdit) pageStatus = "Edit";
    else if (this.isView) pageStatus = "View";
    else if (this.isCopy) pageStatus = "Clone";
    else throw new Error("Invalid page state");

    console.log("pageStatus", pageStatus);

    let organizationId = this.getVarGlobal("deptParentId");
    if (organizationId === "0") {
      organizationId = this.getVarSystem("deptIds").split(",")[0];
    }

    this.setData({ organization_id: organizationId, page_status: pageStatus });
    this.hide([
      "exchange_rate",
      "exchange_rate_myr",
      "exchange_rate_currency",
      "myr_total_amount",
      "total_amount_myr",
    ]);

    const customerType = this.getValue("customer_type");
    switch (pageStatus) {
      case "Add":
        this.display(["draft_status"]);
        await checkAccIntegrationType(organizationId);
        await setPlant(organizationId, pageStatus);
        this.setData({
          sqt_date: new Date().toISOString().split("T")[0],
          customer_type: "Existing Customer",
          print_status: "Pending",
          created_source: 'Web'
        });
        break;

      case "Edit":
        if (customerType === "Existing Customer") {
          const sqtCustomer = this.getValue("sqt_customer_id");
          if (sqtCustomer) {
            this.display("address_grid");
          }
        }

        this.setData({ previous_status: status });

        await enabledUOMField();
        await checkAccIntegrationType(organizationId);
        await displayCustomerType();
        await setPlant(organizationId, pageStatus);
        await disabledField(status);
        await showStatusHTML(status);
        await displayDeliveryMethod();
        await displayTax();
        await displayCurrency();
        await fixValidityPeriod();
        await fetchUnrestrictedQty();
        break;

      case "Clone":
        if (customerType === "Existing Customer") {
          const sqtCustomer = this.getValue("sqt_customer_id");
          if (sqtCustomer) {
            this.display("address_grid");
          }
        }

        this.disabled(
          this.getValue("sqt_no_type") !== -9999 ? ["sqt_no"] : [],
          true
        );
        this.setData({
          sqt_date: new Date().toISOString().split("T")[0],
          sqt_no: null,
          sqt_status: null,
          print_status: "Pending",
          created_source: 'Web'
        });
        this.display(["draft_status"]);

        console.log("Cloning record", this.getValues());
        await setPlant(organizationId, pageStatus);
        await checkAccIntegrationType(organizationId);
        await displayDeliveryMethod();
        await displayTax();
        await displayCustomerType();
        await displayCurrency();
        await fixValidityPeriod();
        await enabledUOMField();
        await fetchUnrestrictedQty();
        break;

      case "View":
        console.log("Viewing record", this.getValues());
        if (customerType === "Existing Customer") {
          const sqtCustomer = this.getValue("sqt_customer_id");
          if (sqtCustomer) {
            this.display("address_grid");
          }
        }
        this.hide([
          "link_billing_address",
          "link_shipping_address",
          "button_save_as_draft",
          "button_issued",
          "sqt_customer_id",
        ]);
        this.display(["sqt_customer_id"]);
        await displayCustomerType();
        await showStatusHTML(status);
        await displayDeliveryMethod();
        await displayCurrency();
        await fixValidityPeriod();
        await displayTax();
        break;
    }
  } catch (error) {
    console.error(error);
    this.$message.error(error.message || "An error occurred");
  }
})();

setTimeout(async () => {
  const maxRetries = 10;
  const interval = 500;
  for (let i = 0; i < maxRetries; i++) {
    const op = await this.onDropdownVisible(
      "sqt_no_type",
      true,
    );
    if (op != null) break;
    await new Promise((resolve) => setTimeout(resolve, interval));
  }
  function getDefaultItem(arr) {
    return arr?.find((item) => item?.item?.is_default === 1);
  }
  var params = this.getComponent("sqt_no");
  const { options } = params;

  const optionsData = this.getOptionData("sqt_no_type") || [];
  const defaultData = getDefaultItem(optionsData);
  if (options?.canManualInput) {
    this.setOptionData("sqt_no_type", [
      { label: "Manual Input", value: -9999 },
      ...optionsData,
    ]);
    if (this.isAdd) {
      this.setData({
        sqt_no_type: defaultData ? defaultData.value : -9999,
      });
    }
  } else if (defaultData) {
    if (this.isAdd) {
      this.setData({ sqt_no_type: defaultData.value });
    }
  }
}, 200);

if(!this.getValue('sqt_delivery_method_id')){
  const fields = ['qt_self_pickup', 'qt_courier_service', 'qt_company_truck','qt_shipping_service','third_party_transporter'];
  this.setData({ 'delivery_method_text': ''});
  this.hide(fields)
}

const data = this.getValues();
const exchangeRate = data.exchange_rate;
const items = data.table_sqt;
let totalGross = 0;
let totalDiscount = 0;
let totalTax = 0;
let totalAmount = 0;

const roundPrice = (value) => {
  return parseFloat(parseFloat(value || 0).toFixed(4));
};

if (Array.isArray(items)) {
  items.forEach((item, index) => {
    // Ensure values are numeric
    const quantity = Number(item.quantity) || 0;
    const unitPrice = roundPrice(item.unit_price) || 0;

    const grossValue = quantity * unitPrice;
    totalGross += roundPrice(grossValue);

    // Set gross value
    this.setData({
      [`table_sqt.${index}.sqt_gross`]: roundPrice(grossValue),
      [`table_sqt.${index}.total_price`]: roundPrice(grossValue),
      sqt_sub_total: roundPrice(totalGross),
    });

    // Get discount, discountUOM, and tax info for this row
    let discount = parseFloat(item.sqt_discount) || 0;
    let discountUOM = item.sqt_discount_uom_id;
    const taxRate = Number(item.sqt_tax_rate_percent) || 0;
    const taxInclusive = item.sqt_tax_inclusive;
    let discountAmount = 0.0;

    if (discount > 0) {
      if (!discountUOM) {
        discountUOM = "Amount";
        this.setData({ [`table_sqt.${index}.sqt_discount_uom_id`]: "Amount" });
      }
    }

    if (discountUOM) {
      // Calculate discount amount using UOM from database
      if (discount !== 0) {
        if (discountUOM === "Amount") {
          discountAmount = roundPrice(discount);
        } else if (discountUOM === "%") {
          discountAmount = roundPrice((grossValue * discount) / 100);
        }

        if (discountAmount > grossValue) {
          discount = 0;
          discountAmount = 0;

          this.setData({
            [`table_sqt.${index}.sqt_discount`]: 0,
            [`table_sqt.${index}.sqt_discount_amount`]: 0,
          });
        } else {
          this.setData({
            [`table_sqt.${index}.sqt_discount_amount`]:
              roundPrice(discountAmount),
          });
        }
      }
    } else {
      this.setData({
        [`table_sqt.${index}.sqt_discount_amount`]: 0,
      });
    }
    // Calculate amount after discount
    const amountAfterDiscount = roundPrice(grossValue - discountAmount);

    // Calculate tax amount based on taxInclusive flag
    let taxAmount = 0;
    let finalAmount = amountAfterDiscount;

    if (taxRate) {
      const taxRateDecimal = taxRate / 100;

      if (taxInclusive === 1) {
        taxAmount = roundPrice(
          amountAfterDiscount - amountAfterDiscount / (1 + taxRateDecimal)
        );
        finalAmount = amountAfterDiscount;
      } else {
        taxAmount = roundPrice(amountAfterDiscount * taxRateDecimal);
        finalAmount = amountAfterDiscount + taxAmount;
      }

      // Set tax amount
      this.setData({
        [`table_sqt.${index}.sqt_taxes_fee_amount`]: taxAmount,
      });
    } else {
      this.setData({
        [`table_sqt.${index}.sqt_taxes_fee_amount`]: 0,
      });
    }

    // Set final amount
    this.setData({
      [`table_sqt.${index}.total_price`]: roundPrice(finalAmount),
    });

    // Subtract previous values before adding new ones
    totalDiscount += roundPrice(discountAmount);
    totalTax += roundPrice(taxAmount);
    totalAmount += roundPrice(finalAmount);

    if (totalTax > 0) {
      this.display(["sqt_total_tax", "total_tax_currency"]);
    }

    // Set the total fields
    this.setData({
      sqt_total_discount: roundPrice(totalDiscount),
      sqt_total_tax: roundPrice(totalTax),
      sqt_totalsum: roundPrice(totalAmount),
    });

    if (!exchangeRate) {
      return;
    } else {
      const myrTotal = exchangeRate * totalAmount;
      this.setData({
        myr_total_amount: roundPrice(myrTotal),
      });
    }
  }); // This closing bracket was missing for the forEach callback
} else {
  console.log("Not an array:", items);
}

