  if (
    !Array.isArray(table_uom_conversion) ||
    table_uom_conversion.length === 0 ||
    !uom
  ) {
    return baseQty;
  }

  const uomConversion = table_uom_conversion.find(
    (conv) => conv.alt_uom_id === uom,
  );

  if (!uomConversion || !uomConversion.base_qty) {
    return baseQty;
  }

  return Math.round((baseQty / uomConversion.base_qty) * 1000) / 1000;
};

const fetchUnrestrictedQty = async (
  itemId,
  item_batch_management,
  serial_number_management,
  stock_control,
  plantId,
  organizationId,
) => {
  try {
    let totalUnrestrictedQtyBase = 0;

    if (serial_number_management === 1) {
      const resSerialBalance = await db
        .collection("item_serial_balance")
        .where({
          material_id: itemId,
          ...(plantId !== organizationId ? { plant_id: plantId || null } : {}),
          organization_id: organizationId,
        })
        .get();

      if (resSerialBalance && resSerialBalance.data.length > 0) {
        const serialBalanceData = resSerialBalance.data;

        totalUnrestrictedQtyBase = serialBalanceData.reduce(
          (sum, balance) => sum + (balance.unrestricted_qty || 0),
          0,
        );
      }
    } else if (
      (serial_number_management !== 1 || !serial_number_management) &&
      item_batch_management === 1 &&
      (stock_control !== 0 || stock_control)
    ) {
      const resBatchBalance = await db
        .collection("item_batch_balance")
        .where({
          material_id: itemId,
          ...(plantId !== organizationId ? { plant_id: plantId || null } : {}),
          organization_id: organizationId,
        })
        .get();

      if (resBatchBalance && resBatchBalance.data.length > 0) {
        const batchBalanceData = resBatchBalance.data;

        totalUnrestrictedQtyBase = batchBalanceData.reduce(
          (sum, balance) => sum + (balance.unrestricted_qty || 0),
          0,
        );
      }
    } else if (
      (serial_number_management !== 1 || !serial_number_management) &&
      (item_batch_management !== 1 || !item_batch_management) &&
      (stock_control !== 0 || stock_control)
    ) {
      const resBalance = await db
        .collection("item_balance")
        .where({
          material_id: itemId,
          ...(plantId !== organizationId ? { plant_id: plantId || null } : {}),
          organization_id: organizationId,
        })
        .get();

      if (resBalance && resBalance.data.length > 0) {
        const balanceData = resBalance.data;

        totalUnrestrictedQtyBase = balanceData.reduce(
          (sum, balance) => sum + (balance.unrestricted_qty || 0),
          0,
        );
      }
    } else {
      totalUnrestrictedQtyBase = 0;
    }

    return totalUnrestrictedQtyBase;
  } catch (error) {
    console.error(error);
  }
};

(async () => {
  const currentItemArray = arguments[0].selectedRecords;
  const rowIndex = arguments[0].rowIndex;
  const docuementType = arguments[0].documentType;
  const sqtLineItems = this.getValue("table_sqt");
  const plantId = this.getValue("sqt_plant");
  let updates = {};
  let latestSQTItems = [];

  if (currentItemArray.length === 0) {
    return;
  }

  let organizationId = this.getVarGlobal("deptParentId");
  if (organizationId === "0") {
    organizationId = this.getVarSystem("deptIds").split(",")[0];
  }

  const currentItem = currentItemArray[0];
  let sqtItemData = {};

  if (docuementType === "SQT") {
    const resSQTItem = await db
      .collection("quotation_rdywe1rx_sub")
      .doc(currentItem.id)
      .get();

    sqtItemData = resSQTItem.data[0];
  } else if (docuementType === "SI") {
    const resSIItem = await db
      .collection("sales_invoice_zt0c3x55_sub")
      .doc(currentItem.id)
      .get();

    sqtItemData = resSIItem.data[0];
  }

  const sqtItem = {
    material_id: sqtItemData.material_id,
    material_name: sqtItemData.material_name,
    sqt_desc: sqtItemData.sqt_desc || sqtItemData.material_desc,
    more_desc: sqtItemData.more_desc,
    quantity: currentItem.quantity,
    sqt_order_uom_id:
      sqtItemData.sqt_order_uom_id || sqtItemData.invoice_qty_uom_id,
    unit_price: currentItem.unit_price,
    sqt_gross: sqtItemData.sqt_gross || sqtItemData.gross,
    sqt_discount: sqtItemData.sqt_discount || sqtItemData.si_discount,
    sqt_discount_uom_id:
      sqtItemData.sqt_discount_uom_id || sqtItemData.si_discount_uom_id,
    sqt_discount_amount:
      sqtItemData.sqt_discount_amount || sqtItemData.discount_amount,
    sqt_taxes_rate_id:
      sqtItemData.sqt_taxes_rate_id || sqtItemData.si_tax_rate_id,
    sqt_tax_rate_percent:
      sqtItemData.sqt_tax_rate_percent || sqtItemData.tax_percent,
    sqt_taxes_fee_amount:
      sqtItemData.sqt_taxes_fee_amount || sqtItemData.tax_amount,
    sqt_tax_inclusive:
      sqtItemData.sqt_tax_inclusive || sqtItemData.si_tax_inclusive,
    total_price: sqtItemData.total_price || sqtItemData.si_amount,
    line_remark_1: sqtItemData.line_remark_1,
    line_remark_2: sqtItemData.line_remark_2,
    item_category_id: sqtItemData.item_category_id,
    line_remark_3: sqtItemData.line_remark_3,
    further_description: sqtItemData.further_description,
    custom_fields: sqtItemData.custom_fields || {},
  };

  latestSQTItems = [...sqtLineItems];
  latestSQTItems[rowIndex] = sqtItem;
  updates["table_sqt"] = latestSQTItems;

  setTimeout(async () => {
    const resItem = await db
      .collection("Item")
      .doc(sqtItemData.material_id)
      .get();
    const itemData = resItem.data[0];

    const initialQty = await fetchUnrestrictedQty(
      itemData.id,
      itemData.item_batch_management,
      itemData.serial_number_management,
      itemData.stock_control,
      plantId,
      organizationId,
    );

    const finalQty = await convertBaseToAlt(
      initialQty,
      itemData.table_uom_conversion,
      sqtItemData.sqt_order_uom_id,
    );

    updates[`table_sqt.${rowIndex}.unrestricted_qty`] = parseFloat(
      finalQty.toFixed(4),
    );
    updates[`table_sqt.${rowIndex}.base_unrestricted_qty`] = parseFloat(
      initialQty.toFixed(4),
    );

    await this.setData(updates);
    this.triggerEvent("SQTCalculation");
  }, 50);
})();

